def record_existing_inactive(apps, schema_editor):
    """Items already deactivated by the testing-era Delete (Item List -> Delete) become Items Trash entries, so they
    show on the Trash screen (who/when blank) and are re-trashed by item number after a rebuild.

    They go through the same zero-and-record step as sales.trash.trash: stock on hand is zeroed with a "Moved to Trash"
    adjustment and the quantity and value are parked on the entry, so Restore puts them back like any trashed item.
    The real store data (10/9 backup) has every item active, so on the store this writes nothing."""
    Item = apps.get_model('sales', 'Item')
    ItemTrash = apps.get_model('sales', 'ItemTrash')
    InventoryAdjustment = apps.get_model('sales', 'InventoryAdjustment')
    for item in Item.objects.filter(active=False).order_by('pk').iterator():
        quantity = value = None
        if item.on_hand is not None and item.on_hand != 0:
            quantity = item.on_hand
            value = (quantity * item.average_cost).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) if item.average_cost is not None else None
            InventoryAdjustment.objects.create(item=item, old_quantity=quantity, new_quantity=Decimal('0'), old_cost=item.average_cost, new_cost=item.average_cost, note='Moved to Trash')
            item.on_hand = Decimal('0')
            item.version += 1
            item.save(update_fields=['on_hand', 'version'])
        ItemTrash.objects.get_or_create(sku=item.sku, defaults=dict(item=item, item_name=(item.name or item.sku)[:200], quantity_zeroed=quantity, value_zeroed=value))


def put_parked_stock_back(apps, schema_editor):
    """Reverse: the Items Trash table is about to be dropped, and with it the only record of the stock zeroed when
    each item was trashed. Put that quantity back on hand first (a "Restored from Trash" adjustment on top of whatever
    moved meanwhile, exactly as Restore does) and leave the items inactive, as the testing-era Delete left them.
    Re-applying 0035 afterwards zeroes and records them again."""
    Item = apps.get_model('sales', 'Item')
    ItemTrash = apps.get_model('sales', 'ItemTrash')
    InventoryAdjustment = apps.get_model('sales', 'InventoryAdjustment')
    for entry in ItemTrash.objects.exclude(quantity_zeroed=None).exclude(quantity_zeroed=0).order_by('pk').iterator():
        item = entry.item or Item.objects.filter(sku=entry.sku).first()
        if item is None or item.active:
            continue  # the item number is not in this data (QB deleted it), or it is live and owns no parked stock
        before = item.on_hand if item.on_hand is not None else Decimal('0')
        InventoryAdjustment.objects.create(item=item, old_quantity=before, new_quantity=before + entry.quantity_zeroed, old_cost=item.average_cost, new_cost=item.average_cost, note='Restored from Trash')
        item.on_hand = before + entry.quantity_zeroed
        item.version += 1
        item.save(update_fields=['on_hand', 'version'])


